//! The server's lifecycle through the library API. The full test needs a
//! resources directory generated by hd-dumper (`HD_RESOURCES=/path`), and is
//! skipped without one.

use std::io::{Read, Write};
use std::path::PathBuf;

use hd_server::{Options, Server};

fn scratch(name: &str) -> PathBuf {
    let dir = std::env::temp_dir().join(format!("hd-server-it-{}-{name}", std::process::id()));
    let _ = std::fs::remove_dir_all(&dir);
    std::fs::create_dir_all(&dir).unwrap();
    dir
}

fn options(dir: &std::path::Path) -> Options {
    let mut options = Options::in_dir(dir);
    options.game_host = Some("127.0.0.1".into());
    options.asset_url = Some("http://assets.invalid/".into());
    options.http_listen = "127.0.0.1:0".into();
    options.game_listen = "127.0.0.1:0".into();
    options
}

#[test]
fn defaults_and_in_dir() {
    let defaults = Options::default();
    assert_eq!(defaults.resources_dir, PathBuf::from("resources"));
    assert_eq!(defaults.http_listen, "127.0.0.1:8080");
    assert!(!defaults.no_dump);
    let rooted = Options::in_dir("/srv/hd");
    assert_eq!(rooted.resources_dir, PathBuf::from("/srv/hd/resources"));
    assert_eq!(rooted.accounts_file, PathBuf::from("/srv/hd/data/accounts.json"));
    assert_eq!(rooted.key_file, PathBuf::from("/srv/hd/dumps/server-key.bin"));
}

#[tokio::test]
async fn missing_resources_are_an_error_not_an_exit() {
    let dir = scratch("missing");
    std::fs::create_dir_all(dir.join("resources")).unwrap();
    std::fs::write(dir.join("resources/exp-levels.csv"), "Level,ExpToNextLevel\n").unwrap();
    let error = Server::start(options(&dir)).await.err().expect("start must fail");
    let text = format!("{error:#}");
    assert!(text.contains("command-schema.json"), "{text}");
    assert!(!text.contains("exp-levels.csv"), "{text}");
    std::fs::remove_dir_all(&dir).unwrap();
}

#[test]
fn public_key_is_stable_and_private() {
    let dir = scratch("key");
    let file = dir.join("keys/server-key.bin");
    let first = hd_server::public_key(&file).unwrap();
    assert_eq!(hd_server::public_key(&file).unwrap(), first);
    #[cfg(unix)]
    {
        use std::os::unix::fs::PermissionsExt;
        let mode = std::fs::metadata(&file).unwrap().permissions().mode();
        assert_eq!(mode & 0o777, 0o600);
    }
    std::fs::remove_dir_all(&dir).unwrap();
}

#[tokio::test]
async fn serves_bootstrap_and_stops_cleanly() {
    let Some(resources) = std::env::var_os("HD_RESOURCES").map(PathBuf::from) else {
        eprintln!("HD_RESOURCES not set; skipping");
        return;
    };
    let dir = scratch("serve");
    let mut opts = options(&dir);
    opts.resources_dir = resources.clone();
    opts.no_dump = true;
    let server = Server::start(opts.clone()).await.unwrap();
    assert_eq!(server.public_key(), hd_server::public_key(&opts.key_file).unwrap());
    let http = server.http_addr();
    let game = server.game_addr();

    let body = tokio::task::spawn_blocking(move || {
        let mut stream = std::net::TcpStream::connect(http).unwrap();
        stream
            .write_all(b"GET /env_settings HTTP/1.1\r\nHost: x\r\nConnection: close\r\n\r\n")
            .unwrap();
        let mut response = String::new();
        stream.read_to_string(&mut response).unwrap();
        response
    })
    .await
    .unwrap();
    assert!(body.starts_with("HTTP/1.1 200"), "{body}");
    assert!(body.contains("127.0.0.1"), "{body}");

    // An open game connection must not keep the server alive.
    let _held = std::net::TcpStream::connect(game).unwrap();
    tokio::time::timeout(std::time::Duration::from_secs(10), server.stop())
        .await
        .expect("stop must not hang on open connections")
        .unwrap();
    assert!(std::net::TcpStream::connect(http).is_err());
    assert!(!dir.join("dumps/server").exists(), "no_dump must not create captures");

    // Same process, same resources: a restart works, on the same ports.
    opts.http_listen = http.to_string();
    opts.game_listen = game.to_string();
    let again = Server::start(opts.clone()).await.unwrap();
    assert_eq!(again.http_addr(), http);
    again.stop().await.unwrap();

    // A different resources directory needs a new process.
    let other = scratch("other");
    std::fs::create_dir_all(other.join("resources")).unwrap();
    for entry in walk(&resources) {
        let target = other.join("resources").join(entry.strip_prefix(&resources).unwrap());
        std::fs::create_dir_all(target.parent().unwrap()).unwrap();
        std::fs::copy(&entry, target).unwrap();
    }
    opts.resources_dir = other.join("resources");
    let error = Server::start(opts).await.err().expect("must refuse");
    assert!(format!("{error:#}").contains("restart the process"), "{error:#}");
    std::fs::remove_dir_all(&dir).unwrap();
    std::fs::remove_dir_all(&other).unwrap();
}

fn walk(dir: &std::path::Path) -> Vec<PathBuf> {
    let mut out = Vec::new();
    for entry in std::fs::read_dir(dir).unwrap() {
        let path = entry.unwrap().path();
        if path.is_dir() {
            out.extend(walk(&path));
        } else {
            out.push(path);
        }
    }
    out
}
